package main
import("fmt";"os";"io/fs";"path/filepath";"encoding/json";"time";"strings";"github.com/leaanthony/dmg/hfsplus";"github.com/leaanthony/dmg/udif")
var modes map[string]uint32
var links=map[string]string{}
func walk(root,dir string)([]*hfsplus.Entry,error){items,e:=os.ReadDir(dir);if e!=nil{return nil,e};out:=[]*hfsplus.Entry{};for _,item:=range items{p:=filepath.Join(dir,item.Name());rel,_:=filepath.Rel(root,p);key:=filepath.ToSlash(rel);if target,ok:=links[key];ok{out=append(out,&hfsplus.Entry{Name:item.Name(),Kind:hfsplus.KindSymlink,Target:target});continue};info,e:=os.Lstat(p);if e!=nil{return nil,e};mode:=uint16(modes[key]&0777);switch{case info.Mode()&fs.ModeSymlink!=0:t,e:=os.Readlink(p);if e!=nil{return nil,e};out=append(out,&hfsplus.Entry{Name:item.Name(),Kind:hfsplus.KindSymlink,Target:filepath.ToSlash(t)});case info.IsDir():c,e:=walk(root,p);if e!=nil{return nil,e};out=append(out,&hfsplus.Entry{Name:item.Name(),Kind:hfsplus.KindDir,Children:c,Mode:0755});default:data,e:=os.ReadFile(p);if e!=nil{return nil,e};if mode==0{mode=0644};out=append(out,&hfsplus.Entry{Name:item.Name(),Kind:hfsplus.KindFile,Data:data,Mode:mode})}};return out,nil}
func main(){if len(os.Args)!=5{panic("source, modes, links and output required")};data,e:=os.ReadFile(os.Args[2]);if e!=nil{panic(e)};if e=json.Unmarshal(data,&modes);e!=nil{panic(e)};data,e=os.ReadFile(os.Args[3]);if e!=nil{panic(e)};for _,line:=range strings.Split(strings.TrimSpace(string(data)),"\n"){parts:=strings.SplitN(strings.TrimSuffix(line,"\r"),"\t",2);if len(parts)==2{links[parts[0]]=parts[1]}};fmt.Println("Preserving symbolic links:",len(links));children,e:=walk(os.Args[1],os.Args[1]);if e!=nil{panic(e)};children=append(children,&hfsplus.Entry{Name:"Applications",Kind:hfsplus.KindSymlink,Target:"/Applications"});vol:=&hfsplus.Volume{Name:"Agent Meter",CreatedAt:time.Date(2026,10,27,0,0,0,0,time.UTC),Children:children};fmt.Println("Building HFS+ volume with Unix permissions and symbolic links");image,e:=hfsplus.Build(vol);if e!=nil{panic(e)};f,e:=os.Create(os.Args[4]);if e!=nil{panic(e)};defer f.Close();fmt.Println("Compressing UDZO disk image");if e=udif.Build(f,image,"whole disk (Apple_HFS : 0)");e!=nil{panic(e)};fmt.Println("DMG created:",os.Args[4])}
